# owner: platform
"""Short text notices to parents about missed days."""

from typing import Iterable, List

from rosterkit.attendance import days_missed
from rosterkit.models import Mark, Student


def _check_owner(student: Student, marks: List[Mark]):
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark for {mark.student_id} given "
                f"with student {student.student_id}"
            )


def _absent_days(marks: List[Mark]) -> list:
    days = days_missed(marks)
    if not days:
        raise ValueError("no absences to write about")
    return days


def _compose(student: Student, days: list) -> str:
    count = len(days)
    unit = "day" if count == 1 else "days"
    lines = [
        f"{student.first_name} {student.last_name} "
        f"missed {count} {unit}:"
    ]
    lines.extend(f"- {when.isoformat()}" for when in days)
    return "\n".join(lines)


def build_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Notice with the name, count and ordered dates."""
    marks = list(marks)
    _check_owner(student, marks)
    return _compose(student, _absent_days(marks))
